@startuml
enum NuRightAnswer {
  New
  Active
  Banned
}
enum OtherAnswer {
  New
  Old
  Shipped
  Delivered
  Closed
}
class ConcreteRightAnswers {
  address : String
  phone : String
  email : String
  isVIP() : Boolean
}
class Answers {
  paidDate : Date
  total : Real
  details : String
}
class Choices {
  creationDate : Date
}
class ConcreteOtherAnswers {
  billingAddress : String
  open : Date
  closed : Date
  isClosed : Boolean
}
class AnswerdBuilder {
  #login : String
  -password : String
  state : NuRightAnswer
}
class MultipleChoicesAnswers {
  number : Integer
  ordered : Date
  shipped : Boolean
  shipTo : String
  total : Real
  status : OtherAnswer
}
class MCRightAnswer {
  quantity : Integer
  price : Real
}
class NumericAnswers {
  name : String
  description : String
}
ConcreteRightAnswers "1" -- "1" AnswerdBuilder : WebUser_Customer
AnswerdBuilder "1" *-- "1" ConcreteOtherAnswers : Customer_Account
@enduml

@startuml
class Piece
class Colonist
class Good
class Role
class Governor
class VictoryPoint
class Doubloon
class TradingHouse
class SupplyBoard
class ColonistShip {
  Num_Colonists : Integer
  -ColonistZone : ColonistZone
}
class ShippingShip {
  Size : Integer
}
enum PlantationType {
  COFFEE
  CORN
  INDIGO
  QUARRY
  SUGAR
  TABACCO
}
class ColonistZone {
  Stackable : Boolean
  Pieces : Colonist
  MaxColonists : Integer
  add(colonist : Colonist) : Boolean
  remove() : Colonist
  isFilled() : Boolean
}
class Building {
  Type
  Cost : Integer
  VictoryPoints : Integer
  Size : Integer
  -ColonistZones : ColonistZone
  -MaxColonists : Integer
  -HasProduced : Boolean
}
class PlayerBoard {
  PlayerID : Integer
  -ColonistZone : ColonistZone
}
class PlantationSupply
class Plantation {
  Type : PlantationType
  -ColonistZone : ColonistZone
  -HasProduced : Boolean
  Plantation(Type : PlantationType) : Plantation
  produce() : Good
}
interface IColonistBoard {
  addColonist() : Boolean
  hasColonist() : Boolean
  removeColonist() : Colonist
}
interface IBoard {
  initializeRound()
  initializeGame()
}
class GoodZone {
  Stackable : Boolean
  Pieces : Good
  add(colonist : Colonist) : Boolean
  remove() : Good
  isFilled() : Boolean
}
@enduml

@startuml
class Student {
  -phone : String
  -email : String
  -surname : String
  -name : String
}
class Teacher {
  -name : String
  -surname : String
  -email : String
  -phone : String
}
class Grade {
  -name : String
  addStudent()
  getStudent()
  getTotal()
}
class Subject
class Note
class Schedule {
  showSchedule()
}
Teacher "0..1" -- "0..1" Grade : Grade_Teacher
Student "0..1" o-- "1" Grade : Student_Grade
Subject "0..1" -- "0..1" Student : Student_Subject
Subject "1" -- "0..1" Note : Note_Subject
Student "1" -- "1" Schedule : Schedule_Student
@enduml
